module LocPolyTest

using Test
using KernelSmoothing
using KernelSmoothing: _equivalentkernel
using LinearAlgebra: LinearAlgebra, Diagonal

# reference values from nprobust 1.0.0, generated by data/lprobust_golden.R
include(joinpath(@__DIR__, "data", "lprobust_golden.jl"))

# the data of the reference values: 400 observations at 101 distinct values
const I = 1:400
const X = round.(mod.(I .* 0.6180339887498949, 1), digits = 2)
const Y = sin.(2π .* X) .+ 0.3 .* sin.(7.3 .* I)
const W = 1.0 .+ mod.(I, 3)
const EVAL = [0, 0.05, 0.3, 0.5, 0.77, 1]

# smooth data without ties
const XS = [mod(0.7548776662466927i, 1.0) for i in 1:500]
const YS = cos.(3 .* XS) .+ 0.2 .* sin.(11.1 .* (1:500))

const NPKERNELS = Dict("epa" => EpanechnikovKernel(), "tri" => TriangularKernel(), "uni" => UniformKernel())

# a weighted least-squares fit of order p at x0, by its definition
function wls(x, y, w, k, x0, h, p)
  X = [(xi - x0)^j for xi in x, j in 0:p]
  D = Diagonal(w .* k.((x .- x0) ./ h))
  return (X' * D * X) \ (X' * D * y)
end

@testset "agrees with nprobust" begin
  for c in LPROBUST
    vce = c.vce == "nn" ? NNVariance(3) : HCVariance(parse(Int, c.vce[3:end]))
    # (compat = true for nprobust's ties of neighbours, which these data on a grid have)
    m = fit(LocalPolynomialRegression, X, Y; weights = c.weighted ? W : nothing, degree = c.p,
            derivative = c.deriv, kernel = NPKERNELS[c.kernel], bandwidth = c.h, pilot = c.b,
            points = EVAL, vce, compat = true)
    @test all(isapprox.(m.h, c.hused; rtol = 1e-14))
    @test all(isapprox.(m.b, c.bused; rtol = 1e-14))
    @test m.nwindow == c.N
    @test all(isapprox.(m.estimate, c.tau_us; rtol = 1e-10))
    @test all(isapprox.(m.estimate_bc, c.tau_bc; rtol = 1e-10))
    @test all(isapprox.(m.se, c.se_us; rtol = 1e-10))
    @test all(isapprox.(m.se_rbc, c.se_rb; rtol = 1e-10))
  end
end

@testset "definition and bias correction" begin
  for p in 0:2, ν in 0:p, k in (EpanechnikovKernel(), TriangularKernel(), GaussianKernel())
    h = 0.12
    m = fit(LocalPolynomialRegression, XS, YS; degree = p, derivative = ν, kernel = k, bandwidth = h,
            points = [0.0, 0.31, 0.5, 0.97], vce = HCVariance(0), minobs = 0)
    for (j, x0) in enumerate(m.points)
      β = wls(XS, YS, ones(500), k, x0, h, p)
      @test m.estimate[j] ≈ factorial(ν) * β[ν + 1] rtol = 1e-10
    end
    # with b = h, the bias-corrected estimate and its robust standard error are those
    # of the fit of order p + 1 (Calonico, Cattaneo and Titiunik 2014)
    m1 = fit(LocalPolynomialRegression, XS, YS; degree = p + 1, derivative = ν, kernel = k,
             bandwidth = h, points = m.points, vce = HCVariance(0), minobs = 0)
    @test m.estimate_bc ≈ m1.estimate rtol = 1e-9
    @test m.se_rbc ≈ m1.se rtol = 1e-9
  end
end

@testset "leverages" begin
  # the leverage polynomial against the solve it replaces
  for p in 0:3
    G = [sum(abs(sin(7i)) * (i / 10 - 0.5)^(a + b) for i in 1:10) for a in 0:p, b in 0:p]
    C = LinearAlgebra.cholesky(LinearAlgebra.Symmetric(G))
    lev = KernelSmoothing._leveragepoly(C, p)
    for u in (-0.9, -0.2, 0.0, 0.4, 1.0)
      r = [u^j for j in 0:p]
      @test evalpoly(u, lev) ≈ LinearAlgebra.dot(r, C \ r) rtol = 1e-12
    end
  end
end

@testset "polynomials are reproduced" begin
  f(x) = 1 + 2x - 3x^2 + 0.5x^3
  df(x, ν) = ν == 0 ? f(x) : ν == 1 ? 2 - 6x + 1.5x^2 : ν == 2 ? -6 + 3x : 3.0
  y3 = f.(XS)
  for p in 1:3, ν in 0:p
    pts = [0.02, 0.4, 0.83]
    m = fit(LocalPolynomialRegression, XS, y3; degree = p, derivative = ν, bandwidth = 0.2, points = pts)
    p == 3 && @test m.estimate ≈ df.(pts, ν) rtol = 1e-8   # order 3 fits a cubic exactly
    p >= 2 && @test m.estimate_bc ≈ df.(pts, ν) rtol = 1e-8   # order p + 1 does
  end
  # a line is fitted exactly by local linear fits, with zero residual standard errors
  m = fit(LocalPolynomialRegression, XS, 2 .- XS; bandwidth = 0.1, vce = HCVariance(0), points = [0.5])
  @test m.estimate ≈ [1.5] && m.se[1] < 1e-12
end

@testset "location and scale" begin
  pts = [0.1, 0.5, 0.9]
  for ν in 0:1
    m = fit(LocalPolynomialRegression, XS, YS; derivative = ν, bandwidth = 0.15, points = pts)
    m2 = fit(LocalPolynomialRegression, 3 .+ 2 .* XS, YS; derivative = ν, bandwidth = 0.3,
             points = 3 .+ 2 .* pts)
    @test m2.estimate ≈ m.estimate ./ 2^ν rtol = 1e-10
    @test m2.se ≈ m.se ./ 2^ν rtol = 1e-10
    @test m2.estimate_bc ≈ m.estimate_bc ./ 2^ν rtol = 1e-10
    @test m2.se_rbc ≈ m.se_rbc ./ 2^ν rtol = 1e-10
  end
  h = bandwidth(RuleOfThumb(), SmoothingData(XS, YS), EpanechnikovKernel())
  @test bandwidth(RuleOfThumb(), SmoothingData(-5 .+ 4 .* XS, YS), EpanechnikovKernel()) ≈ 4h rtol = 1e-10
end

@testset "rule of thumb" begin
  # the constants C_{0,1}(k) of Fan and Gijbels (1996, Table 3.2)
  function C(k)
    B, V = _equivalentkernel(k, 1, 0)
    return (4 * V / (4 * B^2))^(1 / 5)
  end
  @test C(UniformKernel()) ≈ 4.5^(1 / 5)          # 1.351
  @test C(EpanechnikovKernel()) ≈ 15^(1 / 5)      # 1.719
  @test C(BiweightKernel()) ≈ 35^(1 / 5)          # 2.036
  @test C(GaussianKernel()) ≈ (1 / (2 * sqrt(π)))^(1 / 5)   # 0.776
  # the rule by its definition: a global polynomial of order 4 for local linear fits
  d = SmoothingData(XS, YS)
  z = (XS .- sum(XS) / 500) ./ sqrt(sum(abs2, XS .- sum(XS) / 500) / 500)
  P = [zi^j for zi in z, j in 0:4]
  α = P \ YS
  σ2 = sum(abs2, YS .- P * α) / (500 - 5)
  s = sqrt(sum(abs2, XS .- sum(XS) / 500) / 500)
  m2 = [(2α[3] + 6α[4] * zi + 12α[5] * zi^2) / s^2 for zi in z]
  R = maximum(XS) - minimum(XS)
  sel = selectbandwidth(RuleOfThumb(), d, EpanechnikovKernel())
  @test sel.h ≈ 15^(1 / 5) * (σ2 * R / sum(abs2, m2))^(1 / 5) rtol = 1e-10
  @test sel.details.variance ≈ σ2 rtol = 1e-10
  # without a signal the curvature is small, and the bandwidth is capped at the range
  @test bandwidth(RuleOfThumb(), SmoothingData(XS, sin.(11.1 .* (1:500))), EpanechnikovKernel()) <= R
  # local constant fits (p - ν even) use the rule of order 1
  @test selectbandwidth(RuleOfThumb(), d, EpanechnikovKernel(); degree = 0).h ≈ sel.h
  m = fit(LocalPolynomialRegression, XS, YS; bandwidth = RuleOfThumb(), points = [0.5])
  @test m.selection.rule == RuleOfThumb() && m.h == [sel.h]
end

@testset "floors on the windows" begin
  x = vcat(range(0, 0.3; length = 100), range(0.7, 1; length = 100))   # a gap
  y = sin.(3 .* x)
  m = fit(LocalPolynomialRegression, x, y; bandwidth = 0.05, points = [0.1, 0.5, 0.9])
  @test m.floored == [false, true, false]
  @test m.h[2] ≈ knn_distance(SmoothingData(x), 0.5, 21) && m.h[[1, 3]] == [0.05, 0.05]
  @test m.nwindow[2] == 20   # the 21st observation is at the edge, where the weight is zero
  m0 = fit(LocalPolynomialRegression, x, y; bandwidth = 0.05, points = [0.5], minobs = 0)
  @test isnan(m0.estimate[1]) && m0.nwindow == [0] && m0.floored == [false]
end

@testset "identification" begin
  # few distinct values: x = 0, …, 10, thirty times each, so that the windows of
  # width 1 around 0.5 and 5.5 hold two distinct values. The fit of order 1 exists
  # there, the bias correction of order 2 does not; rounding used to let its singular
  # Gram matrix factor, with bias-corrected estimates far off and tiny standard errors.
  x = repeat(0.0:10.0, inner = 30)
  y = sqrt.(x .+ 1) .+ 0.1 .* sin.(7.3 .* (1:330))
  # (without the floors, which would widen the window of the bias correction)
  for h in (0.7, 0.8, 0.9, 1.0), vce in (NNVariance(), HCVariance(0), HCVariance(1), HCVariance(3))
    m = fit(LocalPolynomialRegression, x, y; bandwidth = h, points = [0.5, 5.5], vce, minobs = 0)
    @test m.nunique == [2, 2]
    for (j, x0) in enumerate(m.points)
      @test m.estimate[j] ≈ wls(x, y, ones(330), EpanechnikovKernel(), x0, h, 1)[1] rtol = 1e-10
    end
    @test all(isfinite, m.se)
    @test all(isnan, m.estimate_bc) && all(isnan, m.se_rbc)
  end
  # one distinct value: nothing is identified
  m = fit(LocalPolynomialRegression, x, y; bandwidth = 0.5, points = [3.0], minobs = 0)
  @test isnan(m.estimate[1]) && isnan(m.se[1]) && m.nunique == [1]
  # discrete covariates with few values: the default bandwidths exist
  for nv in (5, 7, 9)
    xd = repeat(collect(range(1.0, 2.0; length = nv)), inner = 300 ÷ nv)
    yd = log.(xd) .+ 0.2 .* sin.(7.3 .* (1:length(xd)))
    m = fit(LocalPolynomialRegression, xd, yd)
    @test all(isfinite, m.h) && all(isfinite, m.estimate)
    # nprobust's stages need more distinct values near the ends; the error says so,
    # and is not wrapped in the exception of a task
    @test_throws ArgumentError fit(LocalPolynomialRegression, xd, yd; compat = true)
  end
  # global pilot fits use the order that the distinct values identify
  xd = repeat([1.0, 2.0, 3.0, 4.0], inner = 25)
  yd = xd .^ 2 .+ 0.1 .* sin.(1:100)
  @test isfinite(bandwidth(RuleOfThumb(), SmoothingData(xd, yd), EpanechnikovKernel()))
  @test bandwidth(RuleOfThumb(), SmoothingData(xd, yd), EpanechnikovKernel(); degree = 3) == 3   # the range
end

@testset "prediction and fitted values" begin
  m = fit(LocalPolynomialRegression, XS, YS; bandwidth = 0.1, points = [0.2, 0.5, 0.7])
  @test predict(m, [0.2, 0.5, 0.7]) ≈ m.estimate rtol = 1e-10
  pts = collect(range(0, 1; length = 700))   # many points: fast sums, several chunks
  @test predict(m, pts) ≈ fit(LocalPolynomialRegression, XS, YS; bandwidth = 0.1, points = pts).estimate rtol = 1e-9
  m1 = fit(LocalPolynomialRegression, XS, YS; derivative = 1, degree = 2, bandwidth = 0.2, points = [0.5])
  @test predict(m1, [0.5]) ≈ m1.estimate rtol = 1e-10
  # fitted values and residuals in the input order
  perm = [mod(37i, 500) + 1 for i in 1:500]
  xp, yp = XS[perm], YS[perm]
  mp = fit(LocalPolynomialRegression, xp, yp; bandwidth = 0.1)
  @test fitted(mp) ≈ predict(mp, xp) rtol = 1e-12
  @test residuals(mp) ≈ yp .- predict(mp, xp) rtol = 1e-12
  @test_throws ArgumentError fitted(m1)
  mv = fit(LocalPolynomialRegression, XS, YS; bandwidth = [0.1, 0.2], points = [0.3, 0.6])
  @test_throws ArgumentError predict(mv, [0.5])
  # a pointwise rule at a single point selects one bandwidth too
  m1 = fit(LocalPolynomialRegression, XS, YS; points = [0.5])
  @test m1.selection.h isa Vector
  @test predict(m1, [0.5]) ≈ m1.estimate rtol = 1e-10
end

@testset "intervals and tables" begin
  m = fit(LocalPolynomialRegression, X, Y; bandwidth = 0.15, points = EVAL)
  c = confint(m)
  @test size(c) == (6, 2) && all(c[:, 1] .< m.estimate_bc .< c[:, 2])
  @test c ≈ hcat(m.estimate_bc .- 1.959963984540054 .* m.se_rbc, m.estimate_bc .+ 1.959963984540054 .* m.se_rbc)
  c90 = confint(m; level = 0.9, method = Conventional())
  @test c90[:, 2] .- c90[:, 1] ≈ 2 * 1.6448536269514722 .* m.se
  @test coef(m) == m.estimate && stderror(m) == m.se && stderror(m; method = RobustBiasCorrected()) == m.se_rbc
  t = coeftable(m)
  @test keys(t) == (:point, :h, :b, :nobs, :nunique, :floored, :estimate, :se, :lower, :upper,
                    :estimate_bc, :se_rbc, :lower_rbc, :upper_rbc)
  @test all(length(v) == 6 for v in t) && t.upper_rbc == c[:, 2]
  @test nobs(m) == 400 && bandwidth(m) == m.h
  @test occursin("95% robust interval", sprint(show, MIME("text/plain"), m))
  @test length(split(sprint(show, MIME("text/plain"), fit(LocalPolynomialRegression, XS, YS; compat = true)), '\n')) == 18
  @test occursin("degree 1", sprint(show, m))
  @test_throws ArgumentError confint(m; level = 1.5)
end

@testset "arguments" begin
  @test_throws ArgumentError fit(LocalPolynomialRegression, SmoothingData(XS))
  @test_throws ArgumentError fit(LocalPolynomialRegression, XS, YS; degree = 1, derivative = 2)
  @test_throws ArgumentError fit(LocalPolynomialRegression, XS, YS; degree = -1)
  @test_throws DimensionMismatch fit(LocalPolynomialRegression, XS, YS; bandwidth = [0.1, 0.2], points = [0.5])
  @test_throws ArgumentError fit(LocalPolynomialRegression, XS, YS; bandwidth = NormalReference())
  @test_throws ArgumentError fit(LocalPolynomialRegression, XS, YS; bandwidth = 0.1, rho = 0)
  @test_throws ArgumentError fit(LocalPolynomialRegression, XS, YS; bandwidth = "wide")
  @test_throws ArgumentError fit(LocalPolynomialRegression, XS, YS; bandwidth = 0.1, points = Float64[])
  @test_throws ArgumentError fit(LocalPolynomialRegression, XS, YS; bandwidth = 0.1, pilot = "wide")
  @test_throws ArgumentError fit(LocalPolynomialRegression, XS, YS; bandwidth = 0.1, points = [0.5, Inf])
  @test_throws ArgumentError HCVariance(4)
  @test_throws ArgumentError NNVariance(0)
  # a pilot bandwidth given directly, and one point given as a number
  m = fit(LocalPolynomialRegression, XS, YS; bandwidth = 0.1, pilot = 0.2, points = 0.5)
  @test m.b == [0.2] && m.points == [0.5]
end

@testset "HC2 and HC3 at a leverage of one" begin
  # the window holds two distinct values, one of them a single observation, whose
  # leverage in the local linear fit is one
  x = [fill(0.0, 30); 1.0; fill(3.0, 30)]
  y = [0.1 .* sin.(1:30); 2.0; 0.1 .* sin.(1:30)]
  for type in (2, 3)
    m = fit(LocalPolynomialRegression, x, y; bandwidth = 0.6, points = [0.5], vce = HCVariance(type))
    @test isnan(only(m.se))
    @test isfinite(only(m.estimate))
  end
end

@testset "defaults: degree, floors by distinct values, ties of neighbours, counts" begin
  x = [mod(0.6180339887498949i, 1) for i in 1:400]
  y = sin.(2π .* x) .+ 0.2 .* cos.(17.3 .* (1:400))
  # the default order is derivative + 1, as in nprobust
  @test fit(LocalPolynomialRegression, x, y; bandwidth = 0.2, points = [0.5], derivative = 1).degree == 2
  @test fit(LocalPolynomialRegression, x, y; bandwidth = 0.2, points = [0.5]).degree == 1
  # four distinct values: the windows are widened until they hold enough distinct
  # values with positive weight, unless compat
  x4 = repeat([1.0, 4 / 3, 5 / 3, 2.0], inner = 75)
  y4 = log.(x4) .+ 0.2 .* sin.(7.3 .* (1:300))
  m = fit(LocalPolynomialRegression, x4, y4; bandwidth = 0.25, points = [1.0, 1.5])
  @test all(isfinite, m.estimate) && all(isfinite, m.estimate_bc) && all(m.floored)
  # at 1.0 the second distinct value is 1/3 away and the third 2/3; at 1.5 the two
  # nearest are 1/6 away, inside the window, and the next two 1/2
  @test m.h ≈ [1 / 2, 1 / 4] && m.b ≈ [1.0, 3 / 4]
  # the bias correction of order 2 at windows that held two distinct values
  x11 = repeat(0.0:10.0, inner = 30)
  m11 = fit(LocalPolynomialRegression, x11, sqrt.(x11 .+ 1); bandwidth = 0.8, points = [0.5, 5.5])
  @test m11.h == [0.8, 0.8] && m11.b ≈ [2.25, 2.25] && all(isfinite, m11.estimate_bc)
  mc = fit(LocalPolynomialRegression, x4, y4; bandwidth = 0.25, points = [1.0, 1.5], compat = true)
  @test isnan(mc.estimate[1]) && mc.h[1] == 0.25
  @test isnan(fit(LocalPolynomialRegression, x4, y4; bandwidth = 0.25, points = [1.0], minobs = 0).estimate[1])
  # predictions use the same floors
  @test predict(fit(LocalPolynomialRegression, x4, y4; bandwidth = 0.25, points = [1.5]), [1.0]) ≈ m.estimate[1:1]
  # an equally spaced design: neighbours at the same distance are tied, so that a shift
  # of the design leaves the standard errors unchanged
  xe = collect(range(0, 1; length = 500))
  ye = sin.(2π .* xe) .+ 0.3 .* cos.(31.7 .* (1:500))
  pts = [0.0, 0.25, 0.5, 0.75, 1.0]
  m0 = fit(LocalPolynomialRegression, xe, ye; bandwidth = 0.1, points = pts)
  m1 = fit(LocalPolynomialRegression, xe .+ 1, ye; bandwidth = 0.1, points = pts .+ 1)
  @test m1.se ≈ m0.se rtol = 1e-10
  @test all(isapprox.(vcov(m1), vcov(m0); rtol = 1e-8, atol = 1e-14))
  # the counts are of the observations with positive weight in the larger window
  mb = fit(LocalPolynomialRegression, x, y; bandwidth = 0.1, pilot = 0.3, points = [0.5])
  @test mb.nwindow == [count(abs.(x .- 0.5) .< 0.3)]
end

end
